<div class="d-flex justify-content-between mb-3"><div><h2 class="fw-bold"><?=e($order['order_no'])?></h2><div class="text-muted">Créée le <?=e($order['created_at'])?></div></div><a href="<?=e(base_url('account'))?>">← Mon compte</a></div><div class="row g-3"><div class="col-lg-8"><div class="km-card p-3"><table class="table"><thead><tr><th>Produit</th><th>Qté</th><th>Prix</th><th>Total</th></tr></thead><tbody><?php foreach($order['items'] as $i):?><tr><td><?=e($i['name'])?></td><td><?=e($i['quantity'])?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach;?></tbody></table><div class="text-end fs-4 fw-bold">Total: <?=money($order['total'])?></div></div></div><div class="col-lg-4"><div class="km-card p-4"><div class="small text-muted">Statut actuel</div><div class="fs-4 fw-bold text-km"><?=e($order['status'])?></div><div class="timeline mt-3"><?php $steps=['NOUVELLE','CONFIRMEE','EN_PREPARATION','PRETE','EN_LIVRAISON','LIVREE'];$idx=array_search($order['status'],$steps,true);foreach($steps as $i=>$s):?><div class="step <?=($idx!==false&&$i<=$idx)?'fw-bold':'text-muted'?>"><?=e($s)?></div><?php endforeach;?></div></div></div></div>